package pgi3pilot

import "testing"

func TestNormalizeLabel(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{name: "spaces", input: "  Keep  Case  ", want: "Keep  Case"},
		{name: "tabs", input: "\tKeep Case\t", want: "Keep Case"},
		{name: "newlines", input: "\nKeep Case\n", want: "Keep Case"},
		{name: "non-breaking spaces", input: "\u00a0Keep Case\u00a0", want: "Keep Case"},
		{name: "empty", input: "", want: ""},
		{name: "whitespace only", input: " \t\n\u00a0", want: ""},
		{name: "interior whitespace and case", input: " \t\n\u00a0Keep  MiXeD\tCase\nWith\u00a0Space\u00a0\n\t ", want: "Keep  MiXeD\tCase\nWith\u00a0Space"},
		{name: "already normalized", input: "Keep  MiXeD\tCase\nWith\u00a0Space", want: "Keep  MiXeD\tCase\nWith\u00a0Space"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := NormalizeLabel(tt.input); got != tt.want {
				t.Errorf("NormalizeLabel(%q) = %q, want %q", tt.input, got, tt.want)
			}
		})
	}
}

